{
  "name": "横河7651单通道直流电源",
  "name_en": "Yokogawa 7651 Single-Channel DC Power Supply",
  "manufacturer": "Yokogawa",
  "description": "横河7651是一台单通道可编程直流电源，用于实验中输出受控的直流电压或电流。根据驱动信息，该设备支持设置电压、电流、输出模式和输出状态，并在参数修改后通过触发使新设定生效，适合器件偏置、基础电学测试和台式自动化控制。",
  "description_en": "The Yokogawa 7651 is a single-channel programmable DC power supply used in labs to source controlled DC voltage or current. Based on the driver evidence, it supports setting voltage, current, output mode, and output state, and requires a trigger after parameter changes for the new settings to take effect. It is suitable for device biasing, basic electrical testing, and bench automation.",
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取/设置输出电流设定值。",
      "description_en": "Get/set the output current setpoint."
    },
    {
      "action_name": "auto-trigger",
      "description": "触发设备应用待生效的参数更改。",
      "description_en": "Trigger the instrument to apply pending parameter changes."
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置输出电压设定值。",
      "description_en": "Get/set the output voltage setpoint."
    },
    {
      "action_name": "auto-channel",
      "description": "获取单个输出通道。",
      "description_en": "Get the single output channel."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置输出模式。",
      "description_en": "Get/set the output mode."
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置输出开关状态。",
      "description_en": "Get/set the output enable state."
    }
  ],
  "tag_hints": [
    "programmable DC source",
    "single-channel power supply",
    "voltage sourcing",
    "current sourcing",
    "electrical biasing",
    "triggered output update",
    "GPIB instrument"
  ]
}

